 ('PER_HIGH_MEDIEVAL_WEST','High & Late Medieval Latin West',1000,1450)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_LEGENDA_AUREA','primary text','Jacobus de Voragine, Legenda Aurea (Golden Legend, c. 1260)','Christian'),
 ('SRC_HILDEGARD_SCIVIAS','primary text','Hildegard of Bingen, Scivias (c. 1151)','Christian'),
 ('SRC_JULIAN_REVELATIONS','primary text','Julian of Norwich, Revelations of Divine Love (c. 1395)','Christian'),
 ('SRC_BONAVENTURE_LEGENDA','primary text','Bonaventure, Legenda Maior (Life of St Francis, c. 1263)','Christian'),
 ('SRC_RAYMOND_CATHERINE','primary text','Raymond of Capua, Legenda Maior of Catherine of Siena (c. 1395)','Christian')
INSERT INTO _e VALUES
 ('ENT_LMW_MENDICANT_SAINTS','Mendicant-Order Saints','Collective','Devotional collective','Christian','preaching/poverty/learning','A','Hub for the saints of the Franciscan, Dominican and related mendicant orders of the 13th-15th c.'),
 ('ENT_LMW_WOMEN_MYSTICS','Medieval Women Visionaries','Collective','Devotional collective','Christian','mysticism/visionary revelation','A','Hub for the visionary women mystics of the high and late medieval Latin West.'),
 ('ENT_LMW_ANSELM','Anselm of Canterbury','Saint','Medieval saint / Doctor of the Church','Christian','theology/scholasticism','A','Benedictine archbishop and scholastic theologian (1033-1109); venerated saint and Doctor of the Church, father of scholasticism.'),
 ('ENT_LMW_PETER_DAMIAN','Peter Damian','Saint','Medieval saint / monastic reformer','Christian','monastic reform/asceticism','A','Camaldolese monk, cardinal and reformer (c.1007-1072); venerated saint and Doctor of the Church.'),
 ('ENT_LMW_ALBERTUS_MAGNUS','Albertus Magnus','Saint','Mendicant founder / Doctor of the Church','Christian','theology/natural philosophy','A','Dominican friar, bishop and polymath (c.1200-1280); teacher of Aquinas, venerated saint and Doctor of the Church.'),
 ('ENT_LMW_AQUINAS','Thomas Aquinas','Saint','Mendicant founder / Doctor of the Church','Christian','theology/scholasticism','A','Dominican friar and theologian (1225-1274); the Angelic Doctor, venerated saint and Doctor of the Church.'),
 ('ENT_LMW_BONAVENTURE','Bonaventure','Saint','Mendicant founder / Doctor of the Church','Christian','theology/Franciscan mysticism','A','Franciscan minister general and theologian (1221-1274); the Seraphic Doctor, biographer of St Francis, venerated saint.'),
 ('ENT_LMW_VINCENT_FERRER','Vincent Ferrer','Saint','Medieval saint / mendicant preacher','Christian','preaching/eschatology','A','Dominican itinerant preacher (1350-1419); apocalyptic missionary, patron of builders, venerated saint.'),
 ('ENT_LMW_BERNARDINO_SIENA','Bernardino of Siena','Saint','Medieval saint / mendicant preacher','Christian','preaching/Holy Name devotion','A','Franciscan Observant preacher (1380-1444); promoter of devotion to the Holy Name of Jesus, venerated saint.'),
 ('ENT_LMW_SIMON_STOCK','Simon Stock','Saint','Mendicant founder / visionary','Christian','Carmelite devotion/Marian scapular','B','Carmelite friar (d. c.1265) traditionally credited with the vision of the Brown Scapular from the Virgin; venerated saint.'),
 ('ENT_LMW_JULIAN_NORWICH','Julian of Norwich','Saint','Visionary mystic','Christian','mysticism/visionary revelation','A','English anchoress and mystic (c.1342-c.1416); author of the Revelations of Divine Love, the first known book in English by a woman; widely venerated.'),
 ('ENT_LMW_MECHTHILD_MAGDEBURG','Mechthild of Magdeburg','Saint','Visionary mystic','Christian','mysticism/bridal mysticism','B','Beguine and Cistercian mystic (c.1207-c.1282); author of The Flowing Light of the Godhead; venerated visionary.'),
 ('ENT_LMW_ANGELA_FOLIGNO','Angela of Foligno','Saint','Visionary mystic','Christian','mysticism/Franciscan penance','B','Franciscan tertiary and mystic (1248-1309); the ''Mistress of Theologians'', author of the Memoriale; canonized 2013.'),
 ('ENT_LMW_CATHERINE_SWEDEN','Catherine of Sweden','Saint','Medieval saint / mystic','Christian','Brigittine devotion/chastity','B','Brigittine abbess (c.1331-1381); daughter of Bridget of Sweden, second abbess of Vadstena, venerated saint.'),
 ('ENT_LMW_FRANCES_ROME','Frances of Rome','Saint','Medieval saint / mystic','Christian','charity/guardian-angel devotion','A','Roman noblewoman, foundress of the Oblates of Mary (1384-1440); mystic granted a visible guardian angel, venerated saint.'),
 ('ENT_LMW_VITUS','Vitus','Saint','Martyr / devotional helper','Christian','protection/epilepsy','B','Early martyr (d. c.303) whose cult flourished in the medieval West; one of the Fourteen Holy Helpers, invoked against epilepsy and ''St Vitus''s Dance''.'),
 ('ENT_LMW_ERASMUS','Erasmus of Formia','Saint','Martyr / devotional helper','Christian','protection/sailors/intestinal ills','B','Martyr-bishop (d. c.303), known as St Elmo; one of the Fourteen Holy Helpers, patron of sailors.'),
 ('ENT_LMW_PANTALEON','Pantaleon','Saint','Martyr / devotional helper','Christian','healing/protection','B','Physician-martyr (d. c.305); one of the Fourteen Holy Helpers in the Latin West, patron of physicians.'),
 ('ENT_LMW_EUSTACE','Eustace','Saint','Martyr / devotional helper','Christian','protection/hunters','B','Legendary martyr converted by a vision of a stag bearing the Cross; one of the Fourteen Holy Helpers, patron of hunters.'),
 ('ENT_LMW_CYRIACUS','Cyriacus','Saint','Martyr / devotional helper','Christian','protection/exorcism','B','Roman deacon-martyr (d. c.303); one of the Fourteen Holy Helpers, invoked against demonic temptation.'),
 ('ENT_LMW_ACACIUS','Acacius','Saint','Martyr / devotional helper','Christian','protection/against headache','C','Legendary soldier-martyr (Achatius); one of the Fourteen Holy Helpers, invoked against headache and in death-agony.');
